const lessons=[{"sentences":[{"speaker":"A","text":"Attention all passengers waiting for the express train to the central district.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.056541666666667},{"speaker":"A","text":"Please note that this service will now depart from platform four instead of platform two.","position":2,"audioStartSeconds":5.256541666666666,"audioEndSeconds":10.669708333333332},{"speaker":"A","text":"This change is necessary because of unexpected signal maintenance work on the main line.","position":3,"audioStartSeconds":10.869708333333334,"audioEndSeconds":16.307833333333335},{"speaker":"A","text":"We apologize for any inconvenience this sudden alteration causes to your morning journey.","position":4,"audioStartSeconds":16.507833333333334,"audioEndSeconds":22.165041666666667},{"speaker":"A","text":"Staff members in bright orange vests are available near the stairs to guide you.","position":5,"audioStartSeconds":22.365041666666666,"audioEndSeconds":27.442375},{"speaker":"A","text":"Please gather your personal belongings before moving safely across the main concourse.","position":6,"audioStartSeconds":27.642375,"audioEndSeconds":33.067625},{"speaker":"A","text":"Thank you for your patience while we improve our regional railway network.","position":7,"audioStartSeconds":33.267625,"audioEndSeconds":37.610416666666666},{"speaker":"A","role":"section-start","text":"Attention all travelers holding valid tickets for the evening coastal bus service.","position":8,"audioStartSeconds":42.610416666666666,"audioEndSeconds":47.997},{"speaker":"A","text":"Due to severe flooding on the coastal highway buses will depart from the rear exit.","position":9,"audioStartSeconds":48.197,"audioEndSeconds":53.40320833333333},{"speaker":"A","text":"Replacement vehicles are waiting outside the station doors to take you directly downtown.","position":10,"audioStartSeconds":53.603208333333335,"audioEndSeconds":59.131541666666664},{"speaker":"A","text":"You must show your original paper ticket to the driver before boarding the vehicle.","position":11,"audioStartSeconds":59.331541666666666,"audioEndSeconds":64.267125},{"speaker":"A","text":"If you need a refund instead of travel please visit our customer service desk.","position":12,"audioStartSeconds":64.467125,"audioEndSeconds":69.55733333333333},{"speaker":"A","text":"Ticket agents inside the main hall will process your requests until eight oclock.","position":13,"audioStartSeconds":69.75733333333334,"audioEndSeconds":74.91195833333333},{"speaker":"A","text":"We advise everyone to check our digital notice boards for further schedule updates.","position":14,"audioStartSeconds":75.11195833333333,"audioEndSeconds":80.39641666666667}],"questions":[{"prompt":"Where is the express train now departing from?","options":["Platform two.","Platform four.","The central district."],"answer":"B","evidenceSentence":2,"evidence":"depart from platform four instead of platform two","explanation":"Thông báo nêu rõ chuyến tàu sẽ khởi hành từ sân ga số bốn thay vì số hai."},{"prompt":"What caused the train platform change?","options":["Signal maintenance work.","Severe weather flooding.","A broken passenger train."],"answer":"A","evidenceSentence":3,"evidence":"unexpected signal maintenance work on the main line","explanation":"Sự thay đổi là do công việc bảo trì tín hiệu bất ngờ trên tuyến chính."},{"prompt":"Who can passengers ask for help near the stairs?","options":["Ticket inspectors.","Staff members in orange vests.","Railway police officers."],"answer":"B","evidenceSentence":5,"evidence":"Staff members in bright orange vests are available","explanation":"Nhân viên mặc áo khoác màu cam sáng túc trực gần cầu thang để hướng dẫn hành khách."},{"prompt":"Why are the coastal buses departing from the rear exit?","options":["Severe highway flooding.","Heavy platform construction.","A blocked main entrance."],"answer":"A","evidenceSentence":9,"evidence":"Due to severe flooding on the coastal highway","explanation":"Xe buýt phải rời đi từ cửa sau do tình trạng ngập lụt nặng trên đường cao tốc ven biển."},{"prompt":"What must travelers show the driver before boarding the replacement bus?","options":["A digital receipt.","An original paper ticket.","An identification card."],"answer":"B","evidenceSentence":11,"evidence":"You must show your original paper ticket to the driver","explanation":"Hành khách phải xuất trình vé giấy gốc cho tài xế trước khi lên xe."},{"prompt":"Where should passengers go if they prefer a refund?","options":["The rear exit doors.","The customer service desk.","The digital notice board."],"answer":"B","evidenceSentence":12,"evidence":"please visit our customer service desk","explanation":"Hành khách muốn hoàn tiền thay vì đi lại có thể đến quầy dịch vụ khách hàng."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
